import path from 'path';
import { fileURLToPath } from 'url';

// This boilerplate is needed to correctly determine directory paths
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// --- Serve Static Files from the 'frontend' folder ---
// This tells Express: "If a request comes in for a file, look for it in the 'frontend' folder"
// The path goes up from 'scroll-server' to 'backend' to 'Swerver' and then into 'frontend'
